import Foundation
import Testing
@testable import TMDBApp

@MainActor
@Suite("Favorites")
struct FavoritesTests {
    private func withSuite(_ body: (UserDefaults, String) throws -> Void) rethrows {
        let name = "FavoritesTests-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: name)!
        defer { defaults.removePersistentDomain(forName: name) }
        try body(defaults, name)
    }

    private func movies() throws -> [Movie] {
        try JSONDecoder.tmdb.decode(PagedResponse<Movie>.self, from: Fixture.data("popular_page1")).results
    }

    @Test func toggleOnOff() throws {
        let m = try movies()[0]
        try withSuite { defaults, _ in
            let vm = FavoritesViewModel(store: UserDefaultsFavoritesStore(defaults: defaults))
            #expect(!vm.isFavorite(m))
            vm.toggle(m)
            #expect(vm.isFavorite(m))
            vm.toggle(m)
            #expect(!vm.isFavorite(m))
            #expect(vm.favorites.isEmpty)
        }
    }

    @Test func persistsAcrossStoreInstances() throws {
        let list = try movies()
        try withSuite { defaults, _ in
            let vm = FavoritesViewModel(store: UserDefaultsFavoritesStore(defaults: defaults))
            vm.toggle(list[0]); vm.toggle(list[1])
            let vm2 = FavoritesViewModel(store: UserDefaultsFavoritesStore(defaults: defaults))
            #expect(vm2.favorites == vm.favorites)
            #expect(vm2.favorites.map(\.title) == [list[0].title, list[1].title])
            #expect(vm2.favorites[0].releaseDate == list[0].releaseDate)
        }
    }

    @Test func orderKeptAndRemoval() throws {
        let list = Array(try movies().prefix(3))
        try withSuite { defaults, _ in
            let store = UserDefaultsFavoritesStore(defaults: defaults)
            let vm = FavoritesViewModel(store: store)
            list.forEach { vm.toggle($0) }
            #expect(vm.favorites.map(\.id) == list.map(\.id))
            vm.remove(at: IndexSet(integer: 1))
            #expect(vm.favorites.map(\.id) == [list[0].id, list[2].id])
            #expect(store.load().map(\.id) == [list[0].id, list[2].id])
        }
    }

    @Test func noDuplicates() throws {
        let m = try movies()[0]
        try withSuite { defaults, _ in
            let store = UserDefaultsFavoritesStore(defaults: defaults)
            store.save([m, m])
            let vm = FavoritesViewModel(store: store)
            vm.toggle(m)   // removes
            vm.toggle(m)   // adds once
            #expect(vm.favorites.filter { $0.id == m.id }.count == 1)
        }
    }
}
